package com.yeyamo_mobile.api.recommendation_service.infrastructure.persistence;import java.io.Serializable;import java.util.Objects;import jakarta.persistence.*;
@Embeddable public class SignalId implements Serializable{@Column(name="user_id",length=120)String userId;@Column(name="source_id",length=160)String sourceId;public SignalId(){}public SignalId(String u,String s){userId=u;sourceId=s;}public boolean equals(Object o){return o instanceof SignalId i&&Objects.equals(userId,i.userId)&&Objects.equals(sourceId,i.sourceId);}public int hashCode(){return Objects.hash(userId,sourceId);}}
